PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "schema_migrations" ("version" varchar NOT NULL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS "ar_internal_metadata" ("key" varchar NOT NULL PRIMARY KEY, "value" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "conducteurs" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "title" varchar, "username" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "fiche_technique_id" varchar, "tempo_range" varchar);
CREATE TABLE IF NOT EXISTS "conducteurlines" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "conducteur_id" varchar, "duree" time, "sequenceaction" varchar, "interpretes" varchar, "lumieres_ambiante" varchar, "lumieres_effet" varchar, "machine_brouillard" varchar, "videoprojection" varchar, "notes_technicien" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "son" varchar, "ordre" varchar);
CREATE TABLE IF NOT EXISTS "fiche_techniques" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name_event" varchar, "eleve_responsable" varchar, "date" varchar, "professeur_referent" varchar, "notes_complementaires" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "plan_de_scene_dessins" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "fiche_technique_id" varchar, "disposition" varchar, "materiel_musicien" varchar, "ordre" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "coord_x" integer, "coord_y" integer, "layer" varchar);
CREATE TABLE IF NOT EXISTS "materiel_necessaires" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "fiche_technique_id" varchar, "materiel_id" varchar, "quantite" varchar, "precisions_observations" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "projet_artistiques" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "fiche_technique_id" integer, "conducteur_id" integer, "title" varchar, "username" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "status" varchar, "style" varchar);
CREATE TABLE IF NOT EXISTS "metier_dependencies" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "materiel_id" integer, "required_item_id" integer, "qty_multiplier" integer, "note" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "styles" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "ambiance_options" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "style_id" integer NOT NULL, "category" varchar, "value" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, CONSTRAINT "fk_rails_afd2696f6f"
FOREIGN KEY ("style_id")
  REFERENCES "styles" ("id")
);
CREATE TABLE IF NOT EXISTS "zones" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "y_min" integer, "y_max" integer, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "sequence_templates" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "label" varchar DEFAULT NULL, "phase" varchar DEFAULT NULL, "target_talent" varchar DEFAULT NULL, "suggested_light" varchar DEFAULT NULL, "intensity" varchar DEFAULT NULL, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "style_id" integer NOT NULL, CONSTRAINT "fk_rails_7369bcc4a7"
FOREIGN KEY ("style_id")
  REFERENCES "styles" ("id")
);
CREATE TABLE IF NOT EXISTS "materiels" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar DEFAULT NULL, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "on_stage" boolean DEFAULT NULL, "maximum" integer DEFAULT NULL, "zone_y" varchar DEFAULT NULL, "power_needed" boolean DEFAULT NULL, "category" varchar DEFAULT NULL, "default_layer" varchar DEFAULT NULL, "requires_power" boolean DEFAULT 0, "is_bundle" boolean DEFAULT 0, "spread" integer DEFAULT NULL, "x_pref" integer, "zone_id" integer DEFAULT NULL, CONSTRAINT "fk_rails_0177061441"
FOREIGN KEY ("zone_id")
  REFERENCES "zones" ("id")
);
CREATE TABLE IF NOT EXISTS "inspiration_resources" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "title" varchar, "url" varchar, "category" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "emotional_markers" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
CREATE TABLE IF NOT EXISTS "conducteurhasmarkers" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "conducteur_id" integer, "emotional_marker_id" integer, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX "index_ambiance_options_on_style_id" ON "ambiance_options" ("style_id");
CREATE INDEX "index_sequence_templates_on_style_id" ON "sequence_templates" ("style_id");
CREATE INDEX "index_materiels_on_zone_id" ON "materiels" ("zone_id");
COMMIT;
